    targetSlideIndex: 32,
    targetSlideTitle: "\u70ED\u529B\u5B66\u8BA1\u7B97\u5E95\u5EA7\uFF1A\u8FDE\u7EED\u6717\u4E4B\u4E07\u52A8\u529B\u5B66\u4E0E\u6982\u7387\u6BD4\u7279\uFF08p-bit\uFF09",
    keywords: ["\u9000\u76F8\u5E72", "\u73AF\u5883\u8D85\u9009\u62E9", "\u6307\u9488\u6001", "\u5BC6\u5EA6\u77E9\u9635", "\u7ECF\u5178\u5B9E\u5728\u6D8C\u73B0", "\u91CF\u5B50\u8FBE\u5C14\u6587\u4E3B\u4E49"],
    ontologicalParadigm: "\u70ED\u529B\u5B66\u4E0E\u7269\u7406\u8BA1\u7B97",
