    sectionOrPage: "\u7B2C\u4E8C\u81F3\u4E94\u7AE0\uFF1A\u5E38\u89C4\u79D1\u5B66\u4E0E\u8303\u5F0F\uFF1B\u7B2C\u4E5D\u81F3\u5341\u7AE0\uFF1A\u79D1\u5B66\u9769\u547D\u4E0E\u4E0D\u53EF\u901A\u7EA6\u6027",
    targetSlideIndex: 39,
